//! Original-owner bounded host behavior fixtures; no dispatcher or mock engine.
use super::*;
use super::super::tests::{self as frame_tests, hooks, Hooks, cursor, owner, retire, pin_ids, install_foreign, restore_foreign};
use frame_tests::control_tests::body_owner;
use crate::experimental_swift_reactor::allocation_tests::measure_extended;
use std::cell::Cell;
thread_local! { pub(super) static PC_OVERFLOW: Cell<bool> = const { Cell::new(false) }; static FIXTURES: Cell<usize> = const { Cell::new(0) }; static STEPS: Cell<usize> = const { Cell::new(0) }; }
struct Bounds;
impl Bounds { fn new() -> Self { FIXTURES.with(|v|v.set(0)); STEPS.with(|v|v.set(0)); Self } }
impl Drop for Bounds { fn drop(&mut self) { if !std::thread::panicking() { println!("MM_BOUND fixtures={} totalSteps={} maxStepsPerFixture=64 maxFrames=3 realPages=584",FIXTURES.with(Cell::get),STEPS.with(Cell::get)); assert!(FIXTURES.with(Cell::get)<=64); assert!(STEPS.with(Cell::get)<=4096); } } }
fn observed(p: &FrameOperationPhase<'_>) -> SwiftRunUsage { p.phase.operation.control.usage(Some(p.phase.operation.wasi.usage())) }
fn storage<'a>() -> FrameOperationStorage<'a> { FrameOperationStorage{preparation:None,entry:None,returned:None,drained:None,controlled:None} }
fn fixture(enter: bool, body: Option<&[u8]>, action: impl FnOnce(&mut FrameOperationPhase<'_>)) {
 FIXTURES.with(|n|n.set(n.get()+1));
 let mut owned=if let Some(b)=body { body_owner(b,false,&[],SwiftRunBudget::default()) } else {owner()};
 let before=owned.control.as_ref().unwrap().usage(None).reservations.construction.current;
 let mut prep=Some(owned.prepare_frames(cursor())); let mut phase=prep.take().unwrap().unwrap();
 if enter {phase.enter(34).unwrap();}
 assert_eq!(phase.phase.parts.memory.len(),584*65536);
 assert!(phase.phase.parts.frames.len()<=3);
 let start=STEPS.with(Cell::get);
 action(&mut phase);
 assert!(STEPS.with(Cell::get)-start<=64);
 hooks(Hooks::default()); PC_OVERFLOW.with(|v|v.set(false));
 let report=phase.drain(); assert_eq!(report.retained_frames,0);
 let debt=report.live_unreconciled;
 let completion=phase.complete(FrameOperationStorage{preparation:prep,..storage()});
 if debt { assert!(matches!(completion,FrameCompletion::Retained(_))); let mut own=Some(owned); assert!(SwiftReactorInstance::cleanup_owned(&mut own).is_err()); assert!(own.is_some()); drop(own); }
 else { assert!(matches!(completion,FrameCompletion::Completed)); assert_eq!(owned.control.as_ref().unwrap().usage(None).reservations.construction.current,before); retire(owned); }
}
fn push(p: &mut FrameOperationPhase<'_>, v: &[Value]) { for x in v {p.phase.push_value(*x).unwrap();} }
fn op(p: &mut FrameOperationPhase<'_>, operation: Operation) -> Result<(),SwiftRunFailure> {
 STEPS.with(|n|n.set(n.get()+1)); let before=observed(p); let mut result=None; assert_eq!(p.memory_operation(operation,&mut result),Ok(()));
 let after=observed(p); assert_eq!((after.instructions,after.instruction_fuel),(before.instructions,before.instruction_fuel));
 assert_eq!(after.live.values.current,p.phase.parts.values.len()); result.unwrap()
}
const LOAD: Operation=Operation::Load{opcode:0x28,offset:0};
const STORE: Operation=Operation::Store{opcode:0x36,offset:0};
const BODY: &[u8]=&[0x41,0,0x28,2,0,0x1a,0x0b];
fn pinned<'a>(p: &mut FrameOperationPhase<'a>, s: &mut FrameOperationStorage<'a>) -> Result<(),SwiftRunFailure> { STEPS.with(|n|n.set(n.get()+1)); memory_pinned_caller_prerequisite(p,s) }
#[test] fn mm01_all_load_store_shapes() { let _b=Bounds::new();
 let expected=[Value::I32(0xf654b381u32 as i32),Value::I64(0xfedcba98f654b381u64 as i64),Value::F32(0xf654b381),Value::F64(0xfedcba98f654b381),Value::I32(-127),Value::I32(129),Value::I32(-19583),Value::I32(45953),Value::I64(-127),Value::I64(129),Value::I64(-19583),Value::I64(45953),Value::I64(-162221183),Value::I64(4132746113)];
 for (i,value) in expected.iter().enumerate(){fixture(true,None,|p|{p.phase.parts.memory[3..11].copy_from_slice(&0xfedcba98f654b381u64.to_le_bytes());push(p,&[Value::I32(3)]);let before=observed(p);op(p,Operation::Load{opcode:0x28+i as u8,offset:0}).unwrap();assert_eq!(p.phase.parts.values.as_slice(),&[*value]);assert_eq!(observed(p).live.values.current,before.live.values.current);assert_eq!(observed(p).execution_work-before.execution_work,2+width(0x28+i as u8) as u64);});}
 for opcode in 0x36..=0x3e {fixture(true,None,|p|{let value=match opcode{0x37|0x3c..=0x3e=>Value::I64(0xfedcba98f654b381u64 as i64),0x38=>Value::F32(0xf654b381),0x39=>Value::F64(0xfedcba98f654b381),_=>Value::I32(0xf654b381u32 as i32)};push(p,&[Value::I32(3),value]);let before=observed(p);op(p,Operation::Store{opcode,offset:0}).unwrap();assert!(p.phase.parts.values.is_empty());let w=width(opcode);assert_eq!(&p.phase.parts.memory[3..3+w],&0xfedcba98f654b381u64.to_le_bytes()[..w]);assert_eq!(observed(p).execution_work-before.execution_work,2+w as u64);});}
}
